// Cockpit interne DISPO — tableau de bord privé (Ludovic & Raphaël).
// Servi en HTML avec les chiffres requêtés en direct à chaque chargement.
// Déployée avec verify_jwt = false : l'accès est protégé par Basic Auth
// (utilisateur « dispo », mot de passe = secret Supabase COCKPIT_PASSWORD).
// Les stats viennent de public.cockpit_stats() (service_role uniquement).
// RevenueCat live optionnel : poser le secret RC_API_KEY (clé API v2).

import { createClient } from "npm:@supabase/supabase-js@2";

const RC_PROJECT = "proje595f8f5";

const TEMPLATE: string = "<title>Cockpit DISPO</title>\n<style>\n@font-face {\n  font-family: 'Instrument Sans';\n  font-style: normal;\n  font-weight: 400 700;\n  font-display: swap;\n  src: url(data:font/woff2;base64,) format('woff2');\n}\n@font-face {\n  font-family: 'Instrument Serif';\n  font-style: italic;\n  font-weight: 400;\n  font-display: swap;\n  src: url(data:font/woff2;base64,) format('woff2');\n}\n\n:root {\n  --ink: #edeaf2;\n  --muted: #9b93a8;\n  --ground: #0f0e14;\n  --panel: #171520;\n  --panel-2: #1d1a28;\n  --line: rgba(237, 234, 242, 0.09);\n  --gold: #e8b84b;\n  --coral: #ff6b5e;\n  --good: #3ecf8e;\n  --brand-grad: linear-gradient(135deg, var(--gold), var(--coral));\n  --shadow: 0 10px 30px rgba(0, 0, 0, 0.35);\n  --track: rgba(237, 234, 242, 0.12);\n}\n@media (prefers-color-scheme: light) {\n  :root {\n    --ink: #241f2e;\n    --muted: #6e6679;\n    --ground: #f8f5ef;\n    --panel: #ffffff;\n    --panel-2: #f2eee6;\n    --line: rgba(36, 31, 46, 0.1);\n    --gold: #c28f1c;\n    --coral: #e6503f;\n    --good: #1d9e66;\n    --shadow: 0 8px 24px rgba(36, 31, 46, 0.08);\n    --track: rgba(36, 31, 46, 0.1);\n  }\n}\n:root[data-theme=\"dark\"] {\n  --ink: #edeaf2;\n  --muted: #9b93a8;\n  --ground: #0f0e14;\n  --panel: #171520;\n  --panel-2: #1d1a28;\n  --line: rgba(237, 234, 242, 0.09);\n  --gold: #e8b84b;\n  --coral: #ff6b5e;\n  --good: #3ecf8e;\n  --shadow: 0 10px 30px rgba(0, 0, 0, 0.35);\n  --track: rgba(237, 234, 242, 0.12);\n}\n:root[data-theme=\"light\"] {\n  --ink: #241f2e;\n  --muted: #6e6679;\n  --ground: #f8f5ef;\n  --panel: #ffffff;\n  --panel-2: #f2eee6;\n  --line: rgba(36, 31, 46, 0.1);\n  --gold: #c28f1c;\n  --coral: #e6503f;\n  --good: #1d9e66;\n  --shadow: 0 8px 24px rgba(36, 31, 46, 0.08);\n  --track: rgba(36, 31, 46, 0.1);\n}\n\n* { box-sizing: border-box; }\nhtml { background: var(--ground); }\nbody {\n  margin: 0;\n  font-family: 'Instrument Sans', system-ui, sans-serif;\n  color: var(--ink);\n  background: var(--ground);\n  line-height: 1.55;\n  -webkit-font-smoothing: antialiased;\n}\n.wrap { max-width: 1040px; margin: 0 auto; padding: 28px 20px 64px; }\n\nem, .serif { font-family: 'Instrument Serif', Georgia, serif; font-style: italic; font-weight: 400; }\n\n/* ---------- header ---------- */\nheader.top {\n  display: flex; align-items: center; gap: 14px; flex-wrap: wrap;\n  padding-bottom: 22px; margin-bottom: 26px; border-bottom: 1px solid var(--line);\n}\n.mark {\n  width: 44px; height: 44px; border-radius: 11px; flex: none;\n  background: var(--brand-grad);\n  display: grid; place-items: center;\n  color: #171017; font-size: 24px; line-height: 1;\n  box-shadow: var(--shadow);\n}\n.titleblock h1 { margin: 0; font-size: 1.35rem; font-weight: 600; letter-spacing: -0.01em; }\n.titleblock h1 em { font-size: 1.5rem; letter-spacing: 0; }\n.titleblock p { margin: 2px 0 0; color: var(--muted); font-size: 0.85rem; }\n.chips { margin-left: auto; display: flex; gap: 8px; flex-wrap: wrap; }\n.chip {\n  font-size: 0.72rem; letter-spacing: 0.06em; text-transform: uppercase;\n  padding: 5px 11px; border-radius: 99px; border: 1px solid var(--line);\n  color: var(--muted); background: var(--panel); white-space: nowrap;\n}\n.chip.live { color: var(--good); border-color: color-mix(in srgb, var(--good) 35%, transparent); }\n\n/* ---------- KPI row ---------- */\n.kpis { display: grid; grid-template-columns: repeat(4, 1fr); gap: 12px; margin-bottom: 14px; }\n@media (max-width: 820px) { .kpis { grid-template-columns: repeat(2, 1fr); } }\n.kpi {\n  background: var(--panel); border: 1px solid var(--line); border-radius: 14px;\n  padding: 16px 18px 14px;\n}\n.kpi .label { font-size: 0.72rem; letter-spacing: 0.08em; text-transform: uppercase; color: var(--muted); }\n.kpi .value {\n  font-size: 2rem; font-weight: 650; letter-spacing: -0.02em; line-height: 1.15;\n  font-variant-numeric: tabular-nums; margin-top: 4px;\n}\n.kpi .value small { font-size: 1rem; font-weight: 500; color: var(--muted); }\n.kpi .sub { font-size: 0.8rem; color: var(--muted); margin-top: 2px; }\n.kpi .sub b { color: var(--ink); font-weight: 600; }\n\n/* ---------- sections / cards ---------- */\n.grid { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }\n@media (max-width: 820px) { .grid { grid-template-columns: 1fr; } }\nsection.card {\n  background: var(--panel); border: 1px solid var(--line); border-radius: 16px;\n  padding: 20px 22px; margin-top: 12px;\n}\nsection.card > h2 {\n  margin: 0 0 4px; font-size: 1.02rem; font-weight: 600; letter-spacing: -0.01em;\n  display: flex; align-items: baseline; gap: 8px;\n}\nsection.card > h2 .dot { width: 8px; height: 8px; border-radius: 50%; background: var(--brand-grad); flex: none; align-self: center; }\nsection.card > p.lead { margin: 0 0 14px; color: var(--muted); font-size: 0.86rem; }\n\n/* progress bars */\n.bar { height: 10px; border-radius: 99px; background: var(--track); overflow: hidden; }\n.bar > i { display: block; height: 100%; border-radius: 99px; background: var(--brand-grad); }\n.bar.good > i { background: var(--good); }\n.barrow { margin: 12px 0 2px; }\n.barrow .meta { display: flex; justify-content: space-between; font-size: 0.85rem; margin-bottom: 6px; }\n.barrow .meta b { font-variant-numeric: tabular-nums; }\n.barrow .meta span { color: var(--muted); }\n\n/* fact tables */\n.facts { display: grid; grid-template-columns: max-content 1fr; gap: 7px 18px; font-size: 0.88rem; margin: 0; }\n.facts dt { color: var(--muted); }\n.facts dd { margin: 0; font-variant-numeric: tabular-nums; overflow-wrap: anywhere; }\n.facts dd b { font-weight: 600; }\n.facts a { color: var(--coral); text-decoration: none; }\n.facts a:hover, .facts a:focus-visible { text-decoration: underline; }\n\n.statgrid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; margin-top: 10px; }\n.stat { background: var(--panel-2); border-radius: 11px; padding: 10px 13px; }\n.stat .n { font-size: 1.3rem; font-weight: 650; font-variant-numeric: tabular-nums; }\n.stat .l { font-size: 0.76rem; color: var(--muted); }\n\n.pill {\n  display: inline-block; font-size: 0.72rem; font-weight: 600; letter-spacing: 0.04em;\n  padding: 2px 9px; border-radius: 99px; vertical-align: middle;\n}\n.pill.ok { color: var(--good); background: color-mix(in srgb, var(--good) 14%, transparent); }\n.pill.wait { color: var(--gold); background: color-mix(in srgb, var(--gold) 16%, transparent); }\n\n.note { font-size: 0.78rem; color: var(--muted); margin: 12px 0 0; }\n\n/* ---------- simulator ---------- */\n.sim { margin-top: 14px; background: var(--panel-2); border-radius: 12px; padding: 16px 18px; }\n.sim .row { display: grid; grid-template-columns: 190px 1fr 74px; gap: 12px; align-items: center; margin-bottom: 10px; font-size: 0.86rem; }\n@media (max-width: 560px) { .sim .row { grid-template-columns: 1fr; gap: 4px; } }\n.sim .row output { text-align: right; font-variant-numeric: tabular-nums; font-weight: 600; }\ninput[type=\"range\"] { width: 100%; accent-color: var(--coral); }\ninput[type=\"range\"]:focus-visible { outline: 2px solid var(--coral); outline-offset: 3px; border-radius: 4px; }\n.sim .results { display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; margin-top: 14px; }\n@media (max-width: 560px) { .sim .results { grid-template-columns: 1fr; } }\n.sim .res { border: 1px solid var(--line); border-radius: 10px; padding: 10px 13px; background: var(--panel); }\n.sim .res .n { font-size: 1.25rem; font-weight: 650; font-variant-numeric: tabular-nums; }\n.sim .res .l { font-size: 0.75rem; color: var(--muted); }\n\n/* ---------- roadmap ---------- */\n.roadmap { display: grid; grid-template-columns: repeat(3, 1fr); gap: 12px; margin-top: 14px; }\n@media (max-width: 820px) { .roadmap { grid-template-columns: 1fr; } }\n.lane { background: var(--panel-2); border-radius: 12px; padding: 14px 15px; }\n.lane h3 { margin: 0 0 10px; font-size: 0.78rem; letter-spacing: 0.08em; text-transform: uppercase; }\n.lane.now h3 { color: var(--coral); }\n.lane.next h3 { color: var(--gold); }\n.lane.later h3 { color: var(--good); }\n.lane ul { margin: 0; padding: 0; list-style: none; display: grid; gap: 9px; }\n.lane li { font-size: 0.85rem; padding-left: 14px; position: relative; }\n.lane li::before { content: \"\"; position: absolute; left: 0; top: 0.52em; width: 5px; height: 5px; border-radius: 50%; background: var(--muted); }\n.lane li b { font-weight: 600; }\n.lane li span { color: var(--muted); display: block; font-size: 0.79rem; }\n\nfooter.foot {\n  margin-top: 34px; padding-top: 18px; border-top: 1px solid var(--line);\n  color: var(--muted); font-size: 0.8rem; display: flex; gap: 14px; flex-wrap: wrap; justify-content: space-between;\n}\n\n@media (prefers-reduced-motion: no-preference) {\n  .bar > i { transition: width 0.6s ease; }\n}\n</style>\n\n<div class=\"wrap\">\n  <header class=\"top\">\n    <div class=\"mark\" aria-hidden=\"true\">&#9834;</div>\n    <div class=\"titleblock\">\n      <h1>Cockpit <em>DISPO</em></h1>\n      <p>Tableau de bord interne — Ludovic &amp; Raphaël</p>\n    </div>\n    <div class=\"chips\">\n      <span class=\"chip live\">Live · {{GENERATED_AT}}</span>\n      <span class=\"chip\">Privé</span>\n    </div>\n  </header>\n\n  <div class=\"kpis\">\n    <div class=\"kpi\">\n      <div class=\"label\">Musiciens réels</div>\n      <div class=\"value\">{{REAL}} <small>/ 100</small></div>\n      <div class=\"sub\">objectif fin octobre</div>\n    </div>\n    <div class=\"kpi\">\n      <div class=\"label\">Actifs 30 jours</div>\n      <div class=\"value\">{{ACTIVE30}} <small>/ 25</small></div>\n      <div class=\"sub\">connexions sur 30 j</div>\n    </div>\n    <div class=\"kpi\">\n      <div class=\"label\">MRR</div>\n      <div class=\"value\">{{MRR}}</div>\n      <div class=\"sub\">{{MRR_SUB}}</div>\n    </div>\n    <div class=\"kpi\">\n      <div class=\"label\">Stockage Supabase</div>\n      <div class=\"value\">{{STO_PCT}}<small> %</small></div>\n      <div class=\"sub\">{{STO_USED}} Mo sur 1 Go (plan Free)</div>\n    </div>\n  </div>\n\n  <section class=\"card\">\n    <h2><span class=\"dot\"></span>Objectif d'adoption — fin octobre 2026</h2>\n    <p class=\"lead\">100 musiciens réels inscrits, dont 25 actifs sur les 30 derniers jours (mesure : Supabase, <code>is_demo = false</code>).</p>\n    <div class=\"barrow\">\n      <div class=\"meta\"><b>{{REAL}} / 100 inscrits réels</b><span>{{REAL_PCT}} %</span></div>\n      <div class=\"bar\"><i style=\"width:{{REAL_PCT}}%\"></i></div>\n    </div>\n    <div class=\"barrow\">\n      <div class=\"meta\"><b>{{ACTIVE30}} / 25 actifs sur 30 j</b><span>{{ACT_PCT}} %</span></div>\n      <div class=\"bar\"><i style=\"width:{{ACT_PCT}}%\"></i></div>\n    </div>\n    <p class=\"note\">Les inscrits réels incluent le compte Apple Review et les comptes de test internes — le vrai compteur démarre au lancement public.</p>\n  </section>\n\n  <div class=\"grid\">\n    <section class=\"card\">\n      <h2><span class=\"dot\"></span>Finances — réel</h2>\n      <p class=\"lead\">{{FIN_SRC}}</p>\n      <dl class=\"facts\">\n        <dt>Revenus (28 j)</dt><dd><b>{{REV28}}</b></dd>\n        <dt>MRR</dt><dd><b>{{MRR}}</b></dd>\n        <dt>Abonnements actifs</dt><dd><b>{{SUBS}}</b></dd>\n        <dt>Essais en cours</dt><dd><b>{{TRIALS}}</b></dd>\n        <dt>Prix Premium</dt><dd>CHF 10 / mois &nbsp;·&nbsp; CHF 60 / an</dd>\n        <dt>Chaîne de paiement</dt><dd><span class=\"pill ok\">Prête</span> RevenueCat + webhook + accord Apple actifs</dd>\n        <dt>Produits App Store</dt><dd><span class=\"pill wait\">Ready to submit</span> partent avec la 1.0</dd>\n      </dl>\n      <p class=\"note\">{{PREMIUM_NOTE}}</p>\n    </section>\n\n    <section class=\"card\">\n      <h2><span class=\"dot\"></span>Revenus attendus — <em>simulateur</em></h2>\n      <p class=\"lead\">Hypothèse : 70 % des abonnés au mensuel, 30 % à l'annuel.</p>\n      <div class=\"sim\">\n        <div class=\"row\">\n          <label for=\"simUsers\">Musiciens inscrits</label>\n          <input type=\"range\" id=\"simUsers\" min=\"10\" max=\"1000\" step=\"10\" value=\"100\">\n          <output id=\"outUsers\" for=\"simUsers\">100</output>\n        </div>\n        <div class=\"row\">\n          <label for=\"simConv\">Conversion Premium</label>\n          <input type=\"range\" id=\"simConv\" min=\"0\" max=\"20\" step=\"0.5\" value=\"5\">\n          <output id=\"outConv\" for=\"simConv\">5 %</output>\n        </div>\n        <div class=\"results\">\n          <div class=\"res\"><div class=\"n\" id=\"resSubs\">5</div><div class=\"l\">abonnés Premium</div></div>\n          <div class=\"res\"><div class=\"n\" id=\"resMrr\">CHF 43</div><div class=\"l\">MRR brut</div></div>\n          <div class=\"res\"><div class=\"n\" id=\"resNet\">CHF 434 / an</div><div class=\"l\">net après Apple (−15 %)</div></div>\n        </div>\n      </div>\n      <p class=\"note\">Commission Apple : 15 % (Small Business Program, &lt; 1 M$ / an). Estimation avant impôts.</p>\n    </section>\n  </div>\n\n  <div class=\"grid\">\n    <section class=\"card\">\n      <h2><span class=\"dot\"></span>Utilisateurs &amp; activité</h2>\n      <p class=\"lead\">Source : base de production Supabase.</p>\n      <div class=\"statgrid\">\n        <div class=\"stat\"><div class=\"n\">{{REAL}}</div><div class=\"l\">profils réels</div></div>\n        <div class=\"stat\"><div class=\"n\">{{DEMO}}</div><div class=\"l\">profils démo</div></div>\n        <div class=\"stat\"><div class=\"n\">{{TOTAL}}</div><div class=\"l\">comptes au total</div></div>\n        <div class=\"stat\"><div class=\"n\">{{SOS}}</div><div class=\"l\">SOS créés</div></div>\n        <div class=\"stat\"><div class=\"n\">{{MSGS}}</div><div class=\"l\">messages</div></div>\n        <div class=\"stat\"><div class=\"n\">{{GROUPS}}</div><div class=\"l\">groupes</div></div><div class=\"stat\"><div class=\"n\">{{NEW7}}</div><div class=\"l\">nouveaux (7 j)</div></div>\n      </div>\n    </section>\n\n    <section class=\"card\">\n      <h2><span class=\"dot\"></span>Stockage Supabase</h2>\n      <p class=\"lead\">Projet <code>cghmmpcwqzpjwgnbiuuw</code> — plan Free, 1 Go inclus.</p>\n      <div class=\"barrow\">\n        <div class=\"meta\"><b>{{STO_USED}} Mo utilisés</b><span>reste ≈ {{STO_LEFT}} Mo</span></div>\n        <div class=\"bar good\"><i style=\"width:{{STO_BAR}}%;min-width:6px\"></i></div>\n      </div>\n      <dl class=\"facts\" style=\"margin-top:12px\">\n        <dt>Fichiers hébergés</dt><dd>{{FILES}} (vidéos, avatars, partitions)</dd>\n        <dt>Capacité restante</dt><dd>≈ {{VIDS_LEFT}} vidéos de démo max (45 Mo pièce) avant de passer au plan Pro</dd>\n        <dt>À surveiller</dt><dd>le quota dès les premières dizaines d'utilisateurs actifs</dd>\n      </dl>\n    </section>\n  </div>\n\n  <section class=\"card\">\n    <h2><span class=\"dot\"></span>Roadmap — 3 mois <span style=\"color:var(--muted);font-weight:400;font-size:0.82rem\">(23.07 → fin octobre 2026)</span></h2>\n    <div class=\"roadmap\">\n      <div class=\"lane now\">\n        <h3>&#128308; Now — sortir la 1.0</h3>\n        <ul>\n          <li><b>Tests TestFlight build 14</b><span>liens d'écoute, vidéos, bouton Apple, invitations à 2 comptes, achat sandbox, push réel</span></li>\n          <li><b>Soumission App Store</b><span>version 1.0 dans ASC — build 14 + 2 abonnements + textes FR/EN/ES prêts ; sur go explicite de Ludovic</span></li>\n          <li><b>Lancement</b><span>répondre à la review, publier, badge App Store sur le site</span></li>\n        </ul>\n      </div>\n      <div class=\"lane next\">\n        <h3>&#128993; Next — propager &amp; retenir</h3>\n        <ul>\n          <li><b>Liens universels</b><span>dispoapp.net → profil / SOS / groupe + bouton « Inviter » — levier viral n°1</span></li>\n          <li><b>Activation &amp; rétention</b><span>centre d'activité in-app, onboarding vers le premier contact</span></li>\n          <li><b>Marketing lancement</b><span>ASO, réseaux, conservatoires &amp; groupes FB romands</span></li>\n          <li><b>Analytics privacy-first</b><span>inscriptions, actifs, SOS — côté Supabase, sans SDK tiers</span></li>\n        </ul>\n      </div>\n      <div class=\"lane later\">\n        <h3>&#128994; Later — consolider</h3>\n        <ul>\n          <li><b>Modération</b><span>tableau minimal des signalements</span></li>\n          <li><b>Optimisation Premium</b><span>seulement avec du trafic réel</span></li>\n          <li><b>Tests UI XCTest</b><span>inscription, SOS, candidature, achat</span></li>\n          <li><b>Fiabilité des remplacements</b><span>signaux positifs uniquement</span></li>\n        </ul>\n      </div>\n    </div>\n    <p class=\"note\">Règle de capacité : 2 chantiers « Next » en parallèle pendant les vacances, 1 seul ensuite.</p>\n  </section>\n\n  <section class=\"card\">\n    <h2><span class=\"dot\"></span>Marque &amp; infos utiles</h2>\n    <div class=\"grid\" style=\"margin-top:10px\">\n      <dl class=\"facts\">\n        <dt>App</dt><dd><b>Dispo</b> — 33 instruments · 42 styles · 7 langues</dd>\n        <dt>Bundle ID</dt><dd>ch.dispo.app</dd>\n        <dt>Version</dt><dd>1.0 (build 14) uploadée — <span class=\"pill wait\">pas encore soumise</span></dd>\n        <dt>Éditeur App Store</dt><dd>Raphaël Herrera</dd>\n        <dt>Contact / support</dt><dd><a href=\"mailto:ludovic@dispoapp.net\">ludovic@dispoapp.net</a> (Ludovic Marie)</dd>\n        <dt>Site</dt><dd><a href=\"https://dispoapp.net\" rel=\"noopener\">dispoapp.net</a> — FR/EN, Vercel</dd>\n        <dt>Confidentialité</dt><dd><a href=\"https://dispoapp.net/privacy\" rel=\"noopener\">dispoapp.net/privacy</a></dd>\n      </dl>\n      <dl class=\"facts\">\n        <dt>Dépôt app</dt><dd><a href=\"https://github.com/ludovic111/Dispo\" rel=\"noopener\">github.com/ludovic111/Dispo</a></dd>\n        <dt>Dépôt site</dt><dd><a href=\"https://github.com/ludovic111/Dispo-Website\" rel=\"noopener\">github.com/ludovic111/Dispo-Website</a></dd>\n        <dt>Backend</dt><dd>Supabase <code>cghmmpcwqzpjwgnbiuuw</code></dd>\n        <dt>Paiements</dt><dd>RevenueCat (projet « Dispo ») + StoreKit</dd>\n        <dt>Push</dt><dd>APNs configuré (clé « Dispo APNs »)</dd>\n        <dt>Compte App Review</dt><dd>applereview@demo.dispo.ch</dd>\n        <dt>Compte sandbox</dt><dd>sandbox@demo.dispo.ch (achats de test)</dd>\n      </dl>\n    </div>\n    <p class=\"note\">Aucun mot de passe ni clé ici, volontairement — ils restent dans le trousseau et le dossier « Secrets-Apple ».</p>\n  </section>\n\n  <footer class=\"foot\">\n    <span>Données live Supabase — page générée le {{GENERATED_AT}}.</span>\n    <span>Recharge la page pour actualiser.</span>\n  </footer>\n</div>\n\n<script>\n(function () {\n  var users = document.getElementById('simUsers');\n  var conv = document.getElementById('simConv');\n  var fmt = function (n) { return 'CHF ' + Math.round(n).toLocaleString('fr-CH'); };\n  function update() {\n    var u = +users.value, c = +conv.value / 100;\n    var subs = Math.round(u * c);\n    var mrr = subs * (0.7 * 10 + 0.3 * 5);   /* annuel CHF 60 → CHF 5/mois */\n    var netYear = mrr * 12 * 0.85;\n    document.getElementById('outUsers').textContent = u.toLocaleString('fr-CH');\n    document.getElementById('outConv').textContent = (+conv.value).toLocaleString('fr-CH') + ' %';\n    document.getElementById('resSubs').textContent = subs.toLocaleString('fr-CH');\n    document.getElementById('resMrr').textContent = fmt(mrr);\n    document.getElementById('resNet').textContent = fmt(netYear) + ' / an';\n  }\n  users.addEventListener('input', update);\n  conv.addEventListener('input', update);\n  update();\n})();\n</script>\n";

const nf = new Intl.NumberFormat("fr-CH");
const nf1 = new Intl.NumberFormat("fr-CH", { minimumFractionDigits: 1, maximumFractionDigits: 1 });
const chf = (n: number) => "CHF " + nf.format(Math.round(n));

function unauthorized(): Response {
  return new Response("Authentification requise.", {
    status: 401,
    headers: { "WWW-Authenticate": 'Basic realm="Cockpit DISPO", charset="UTF-8"' },
  });
}

Deno.serve(async (req: Request) => {
  const pass = Deno.env.get("COCKPIT_PASSWORD") ?? "";
  const auth = req.headers.get("authorization") ?? "";
  if (!pass || auth !== "Basic " + btoa("dispo:" + pass)) return unauthorized();

  const supa = createClient(
    Deno.env.get("SUPABASE_URL")!,
    Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!,
  );
  const { data, error } = await supa.rpc("cockpit_stats");
  if (error || !data) {
    return new Response("Erreur stats : " + (error?.message ?? "réponse vide"), { status: 500 });
  }
  const s = data as Record<string, number>;

  // RevenueCat live, seulement si la clé API est posée en secret.
  let rc: { mrr: number; revenue: number; subs: number; trials: number } | null = null;
  const rcKey = Deno.env.get("RC_API_KEY");
  if (rcKey) {
    try {
      const r = await fetch(
        `https://api.revenuecat.com/v2/projects/${RC_PROJECT}/metrics/overview?currency=CHF`,
        { headers: { Authorization: "Bearer " + rcKey } },
      );
      if (r.ok) {
        const j = await r.json();
        const get = (id: string) =>
          Number(j.metrics?.find((m: { id: string }) => m.id === id)?.value ?? 0);
        rc = {
          mrr: get("mrr"),
          revenue: get("revenue"),
          subs: get("active_subscriptions"),
          trials: get("active_trials"),
        };
      }
    } catch (_) {
      // RevenueCat indisponible : on sert le repli serveur.
    }
  }

  const generatedAt = new Intl.DateTimeFormat("fr-CH", {
    dateStyle: "medium",
    timeStyle: "short",
    timeZone: "Europe/Zurich",
  }).format(new Date());

  const quotaMB = 1024; // plan Free : 1 Go de Storage
  const stoMB = Number(s.storage_bytes) / (1024 * 1024);
  const stoPct = (stoMB / quotaMB) * 100;

  const map: Record<string, string> = {
    GENERATED_AT: generatedAt,
    REAL: nf.format(s.real_profiles),
    REAL_PCT: String(Math.min(100, Math.round(s.real_profiles))),
    ACTIVE30: nf.format(s.active_30d),
    ACT_PCT: String(Math.min(100, Math.round((s.active_30d / 25) * 100))),
    MRR: rc ? chf(rc.mrr) : "CHF 0",
    MRR_SUB: rc
      ? nf.format(rc.subs) + " abonnement(s) actif(s)"
      : "0 abonnement payant — app pas encore sortie",
    REV28: rc ? chf(rc.revenue) : "CHF 0",
    SUBS: rc ? nf.format(rc.subs) : "0",
    TRIALS: rc ? nf.format(rc.trials) : "0",
    FIN_SRC: rc
      ? "Source : RevenueCat (live, 28 derniers jours)."
      : "RevenueCat live pas branché (secret RC_API_KEY absent) — chiffres serveur en attendant.",
    PREMIUM_NOTE:
      nf.format(s.premium_real) +
      " profil(s) « premium » en base (flags de test inclus) — la source de vérité des paiements est RevenueCat, synchronisée par webhook.",
    DEMO: nf.format(s.demo_profiles),
    TOTAL: nf.format(s.auth_users),
    SOS: nf.format(s.sos_total),
    MSGS: nf.format(s.messages_total + s.group_messages_total),
    GROUPS: nf.format(s.groups_total),
    NEW7: nf.format(s.new_7d),
    STO_PCT: nf1.format(stoPct),
    STO_USED: nf1.format(stoMB),
    STO_LEFT: nf.format(Math.round(quotaMB - stoMB)),
    STO_BAR: String(Math.max(0.6, Math.min(100, Number(stoPct.toFixed(1))))),
    FILES: nf.format(s.storage_objects),
    VIDS_LEFT: nf.format(Math.floor((quotaMB - stoMB) / 45)),
  };

  let html = TEMPLATE;
  for (const [k, v] of Object.entries(map)) html = html.replaceAll("{{" + k + "}}", v);
  html =
    '<!doctype html><html lang="fr"><head><meta charset="utf-8">' +
    '<meta name="viewport" content="width=device-width, initial-scale=1">' +
    '<meta name="robots" content="noindex, nofollow">' +
    html +
    "</html>";

  return new Response(html, {
    headers: {
      "content-type": "text/html; charset=utf-8",
      "cache-control": "no-store",
      "x-robots-tag": "noindex, nofollow",
    },
  });
});
